// roughly what the compiler turns it into:
var e = ReadOrdersAsync().GetAsyncEnumerator();   // 1) the body hasn't started
try
{
    while (await e.MoveNextAsync())   // 2–5) ValueTask<bool>: run to the next yield
        Handle(e.Current);            // 3) the item; the generator is parked at yield
}
finally { await e.DisposeAsync(); }   // 6) the generator's finally — even after break

